mapper.select:
SELECT m.id, m.brand_id, b.brand_name, m.model_name, m.category_code, m.seats, m.gearbox, m.fuel_type, m.displacement, m.guide_price, m.deposit, m.cover_image, m.description, m.sort_no, m.status, m.create_time, (SELECT COUNT(*) FROM vehicle v WHERE v.model_id = m.id AND v.deleted = 0) AS vehicle_count, (SELECT MIN(v.daily_price) FROM vehicle v WHERE v.model_id = m.id AND v.deleted = 0) AS min_daily_price FROM vehicle_model m LEFT JOIN vehicle_brand b ON b.id = m.brand_id AND b.deleted = 0 WHERE m.deleted = 0
AND m.brand_id = #{q.brandId}
AND m.category_code = #{q.categoryCode}
AND m.status = #{q.status}
AND (m.model_name LIKE CONCAT('%', #{q.keyword}, '%') OR b.brand_name LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY b.sort_no ASC, m.sort_no ASC, m.id ASC

SELECT m.id, m.brand_id, b.brand_name, m.model_name, m.category_code, m.guide_price, m.deposit, m.status FROM vehicle_model m LEFT JOIN vehicle_brand b ON b.id = m.brand_id AND b.deleted = 0 WHERE m.deleted = 0 AND m.status = 1
AND m.brand_id = #{brandId}
ORDER BY b.sort_no ASC, m.sort_no ASC, m.id ASC

SELECT v.id, v.vehicle_no, v.license_plate, v.vin, v.color, v.brand_id, b.brand_name, v.model_id, m.model_name, m.category_code, v.store_id, s.store_name, v.current_mileage, v.daily_price, v.deposit, v.discount_rate, v.register_date, v.status, v.rent_count, v.view_count, v.description, v.create_time, (SELECT o.order_no FROM order_item oi JOIN lease_order o ON o.id = oi.order_id AND o.deleted = 0 WHERE oi.vehicle_id = v.id AND o.status IN ('WAIT_PAY', 'WAIT_PICKUP', 'IN_USE', 'WAIT_RETURN', 'OVERDUE') ORDER BY o.start_date ASC LIMIT 1) AS active_order_no, (SELECT o.status FROM order_item oi JOIN lease_order o ON o.id = oi.order_id AND o.deleted = 0 WHERE oi.vehicle_id = v.id AND o.status IN ('WAIT_PAY', 'WAIT_PICKUP', 'IN_USE', 'WAIT_RETURN', 'OVERDUE') ORDER BY o.start_date ASC LIMIT 1) AS active_order_status, (SELECT o.start_date FROM order_item oi JOIN lease_order o ON o.id = oi.order_id AND o.deleted = 0 WHERE oi.vehicle_id = v.id AND o.status IN ('WAIT_PAY', 'WAIT_PICKUP', 'IN_USE', 'WAIT_RETURN', 'OVERDUE') ORDER BY o.start_date ASC LIMIT 1) AS active_start_date, (SELECT o.end_date FROM order_item oi JOIN lease_order o ON o.id = oi.order_id AND o.deleted = 0 WHERE oi.vehicle_id = v.id AND o.status IN ('WAIT_PAY', 'WAIT_PICKUP', 'IN_USE', 'WAIT_RETURN', 'OVERDUE') ORDER BY o.start_date ASC LIMIT 1) AS active_end_date, (SELECT MAX(i.end_date) FROM vehicle_insurance i WHERE i.vehicle_id = v.id AND i.deleted = 0 AND i.status = 1) AS insurance_end_date, (SELECT mt.next_date FROM vehicle_maintenance mt WHERE mt.vehicle_id = v.id AND mt.deleted = 0 AND mt.next_date IS NOT NULL ORDER BY mt.next_date DESC LIMIT 1) AS next_maintain_date FROM vehicle v LEFT JOIN vehicle_model m ON m.id = v.model_id AND m.deleted = 0 LEFT JOIN vehicle_brand b ON b.id = v.brand_id AND b.deleted = 0 LEFT JOIN store s ON s.id = v.store_id AND s.deleted = 0 WHERE v.deleted = 0
AND v.status = #{q.status}
AND v.store_id = #{q.storeId}
AND v.brand_id = #{q.brandId}
AND (v.license_plate LIKE CONCAT('%', #{q.keyword}, '%') OR v.vehicle_no LIKE CONCAT('%', #{q.keyword}, '%') OR v.vin LIKE CONCAT('%', #{q.keyword}, '%') OR m.model_name LIKE CONCAT('%', #{q.keyword}, '%') OR b.brand_name LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY v.store_id ASC, v.status ASC, v.id ASC

SELECT mt.id, mt.vehicle_id, v.vehicle_no, v.license_plate, m.model_name, b.brand_name, v.store_id, s.store_name, mt.maint_type, mt.maint_date, mt.mileage, mt.cost, mt.content, u.real_name AS operator_name, mt.next_date, mt.remark, mt.create_time FROM vehicle_maintenance mt LEFT JOIN vehicle v ON v.id = mt.vehicle_id LEFT JOIN vehicle_model m ON m.id = v.model_id AND m.deleted = 0 LEFT JOIN vehicle_brand b ON b.id = v.brand_id AND b.deleted = 0 LEFT JOIN store s ON s.id = v.store_id AND s.deleted = 0 LEFT JOIN sys_user u ON u.id = mt.operator_id WHERE mt.deleted = 0
AND mt.maint_type = #{q.maintType}
AND v.store_id = #{q.storeId}
AND mt.vehicle_id = #{q.vehicleId}
AND (v.license_plate LIKE CONCAT('%', #{q.keyword}, '%') OR v.vehicle_no LIKE CONCAT('%', #{q.keyword}, '%') OR mt.content LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY mt.maint_date DESC, mt.id DESC

SELECT i.id, i.vehicle_id, v.vehicle_no, v.license_plate, b.brand_name, m.model_name, v.store_id, s.store_name, i.insurance_type, i.insurer, i.policy_no, i.start_date, i.end_date, i.premium, i.status, i.create_time, DATEDIFF(i.end_date, CURDATE()) AS days_to_expire FROM vehicle_insurance i LEFT JOIN vehicle v ON v.id = i.vehicle_id LEFT JOIN vehicle_model m ON m.id = v.model_id AND m.deleted = 0 LEFT JOIN vehicle_brand b ON b.id = v.brand_id AND b.deleted = 0 LEFT JOIN store s ON s.id = v.store_id AND s.deleted = 0 WHERE i.deleted = 0
AND i.insurance_type = #{q.insuranceType}
AND v.store_id = #{q.storeId}
AND i.status = #{q.status}
AND i.status = 1 AND i.end_date <= DATE_ADD(CURDATE(), INTERVAL 30 DAY)
AND (v.license_plate LIKE CONCAT('%', #{q.keyword}, '%') OR i.policy_no LIKE CONCAT('%', #{q.keyword}, '%') OR i.insurer LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY i.status DESC, i.end_date ASC, i.id DESC
